import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

// #101: the mana font ships as a WOFF2 subset with only the symbols the app
// can show, generated by `npm run fonts:mana`.
const css = readFileSync('app/assets/css/mana.css', 'utf8');
const has = (name: string) => css.includes(`.ms-${name}::before`);

/** mana-font classes the app's own code names. */
function usedClasses() {
  const names = new Set<string>();
  const files = import.meta.glob('/app/**/*.{vue,ts}', {
    query: '?raw',
    import: 'default',
    eager: true,
  }) as Record<string, string>;
  for (const source of Object.values(files))
    for (const [, name] of source.matchAll(
      /ms-((?:ability|counter)-[a-z-]+|tap|untap)\b/g,
    ))
      names.add(name!);
  return names;
}

describe('mana font subset', () => {
  it('loads one WOFF2 file and no other formats or fonts', () => {
    const faces = css.match(/@font-face\s*{[^}]*}/g) ?? [];

    expect(faces).toHaveLength(1);
    expect(faces[0]).toMatch(/url\("?[^)"]*\.woff2"?\)\s*format\("woff2"\)/);
    expect(faces[0]).not.toMatch(/\.(woff|ttf|eot|svg)["?)]/);
  });

  it('keeps every symbol the app names', () => {
    const missing = [...usedClasses()].filter((name) => !has(name));

    expect(missing, 'run `npm run fonts:mana`').toEqual([]);
  });

  it('keeps the symbols Scryfall card text can contain', () => {
    const symbols = [
      'w',
      'u',
      'b',
      'r',
      'g',
      'c',
      's',
      'x',
      'e',
      'p',
      '0',
      '1',
      '15',
      '20',
      'wu',
      'bg',
      '2w',
      'wp',
      'cw',
      'chaos',
      'tap',
      'untap',
    ];

    expect(symbols.filter((name) => !has(name))).toEqual([]);
  });

  it('drops symbol families the app never shows', () => {
    for (const family of ['watermark', 'guild', 'clan', 'dfc', 'loyalty'])
      expect(css, family).not.toContain(`.ms-${family}-`);
    expect(has('ability-ward')).toBe(false);
  });
});
